const $ = (id) => document.getElementById(id);
const load = (k, d) => {
  try { const v = JSON.parse(localStorage.getItem(k)); return v === null ? d : v; }
  catch { return d; }
};
const save = (k, v) => localStorage.setItem(k, JSON.stringify(v));
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const channel = ("BroadcastChannel" in window) ? new BroadcastChannel(CHANNEL) : null;

function toast(text) {
  const el = $("toast");
  el.textContent = text;
  el.classList.add("show");
  clearTimeout(toast._t);
  toast._t = setTimeout(() => el.classList.remove("show"), 2200);
}

function openModal() {
  $("overlay").classList.add("show");
  $("modal").classList.add("show");
}

function closeModal() {
  $("overlay").classList.remove("show");
  $("modal").classList.remove("show");
}

function showTime() {
  $("currentTime").textContent = new Date().toLocaleString("id-ID", { weekday: "short", hour: "2-digit", minute: "2-digit" });
}

const gradient = (i) => {
  const [a, b] = palettes[i % palettes.length];
  return `linear-gradient(135deg, ${a}, ${b})`;
};

function myId() {
  let id = sessionStorage.getItem("mova-id");
  if (!id) { id = crypto.randomUUID(); sessionStorage.setItem("mova-id", id); }
  return id;
}
