function upsertUser(username, p) {
  const list = load(KEYS.users, []);
  const item = {
    username,
    displayName: p.displayName || "",
    bio: p.bio || "",
    links: p.links || [],
    bannerType: p.bannerType || "",
    bannerData: p.bannerData || ""
  };
  const i = list.findIndex((u) => u.username === username);
  if (i >= 0) list[i] = item; else list.push(item);
  save(KEYS.users, list);
}

/* ---------- Kartu ---------- */

