function bindOpen(el) {
  el.querySelectorAll("[data-open]").forEach((c) => {
    c.onclick = () => openDetail(c.dataset.open, c.dataset.id);
  });
}

function fillGrid(el, html) {
  el.innerHTML = html || `<p class="empty">Tidak ada hasil. Coba kata kunci lain.</p>`;
  bindOpen(el);
}

function renderFilters(el, cats, active, onPick) {
  el.innerHTML = cats.map((c) => `<button class="chip ${c === active ? "active" : ""}" data-cat="${esc(c)}">${esc(c)}</button>`).join("");
  el.querySelectorAll("button").forEach((btn) => { btn.onclick = () => onPick(btn.dataset.cat); });
}

const uniqueCats = (list) => ["Semua", ...new Set(list.map((x) => x.cat))];
const matchQuery = (item) => !state.query || Object.values(item).join(" ").toLowerCase().includes(state.query);

/* ---------- Render halaman ---------- */

function renderSong(el) {
  const src = spotifyEmbed(DEFAULT_SONG.url || "");
  el.innerHTML = `<h3>${esc(DEFAULT_SONG.title)}</h3>` + (src
    ? `<iframe class="spotify-frame" src="${src}" height="152" frameborder="0" allow="autoplay; clipboard-write; encrypted-media" loading="lazy"></iframe>`
    : `<p class="muted" style="margin-top:8px">Lagu default belum tersedia.</p>`);
}

function renderHome() {
  $("statVideos").textContent = videos.length;
  $("statPresets").textContent = presets.length;
  fillGrid($("homeTrending"), videos.slice(0, 4).map(videoCard).join(""));
  fillGrid($("homePresets"), presets.slice(0, 4).map(presetCard).join(""));
  renderSong($("homeSong"));
}

function renderVideos() {
  renderFilters($("videoFilters"), uniqueCats(videos), state.videoCat, (c) => { state.videoCat = c; renderVideos(); });
  const list = videos.filter((v) => (state.videoCat === "Semua" || v.cat === state.videoCat) && matchQuery(v));
  fillGrid($("videoGrid"), list.map(videoCard).join(""));
}

function renderShared() {
  const q = state.query;
  const list = load(KEYS.shared, []).filter((s) => !q || (s.title + " " + s.desc).toLowerCase().includes(q));
  fillGrid($("sharedGrid"), list.map(sharedCard).join(""));
}

function renderPresets() {
  renderFilters($("presetFilters"), uniqueCats(presets), state.presetCat, (c) => { state.presetCat = c; renderPresets(); });
  const list = presets.filter((p) => (state.presetCat === "Semua" || p.cat === state.presetCat) && matchQuery(p));
  fillGrid($("presetGrid"), list.map(presetCard).join(""));
  renderShared();
}

function renderTemplates() {
  renderFilters($("templateFilters"), uniqueCats(templates), state.templateCat, (c) => { state.templateCat = c; renderTemplates(); });
  const list = templates.filter((t) => (state.templateCat === "Semua" || t.cat === state.templateCat) && matchQuery(t));
  fillGrid($("templateGrid"), list.map(templateCard).join(""));
}

function renderMusic() {
  renderSong($("defaultSong"));
}

function renderStickers() {
  $("stickerPick").innerHTML = stickers.map((s, i) => `<button class="chip" data-st="${i}">${s.svg}</button>`).join("");
  $("stickerPick").querySelectorAll("[data-st]").forEach((b) => { b.onclick = () => addSticker(stickers[+b.dataset.st]); });
}

function addSticker(s) {
  const stage = $("stage");
  const el = document.createElement("div");
  el.className = "stk anim-" + s.a;
  el.innerHTML = s.svg;
  el.style.left = (30 + Math.random() * 40) + "%";
  el.style.top = (30 + Math.random() * 40) + "%";
  el.addEventListener("pointerdown", (e) => startDrag(e, el));
  stage.appendChild(el);
}

function startDrag(e, el) {
  e.preventDefault();
  const stage = $("stage");
  const move = (ev) => {
    const r = stage.getBoundingClientRect();
    el.style.left = ((ev.clientX - r.left) / r.width * 100) + "%";
    el.style.top = ((ev.clientY - r.top) / r.height * 100) + "%";
  };
  const up = () => {
    window.removeEventListener("pointermove", move);
    window.removeEventListener("pointerup", up);
  };
  window.addEventListener("pointermove", move);
  window.addEventListener("pointerup", up);
}

function resetGame() {
  state.ttt = { board: Array(9).fill(""), turn: "X", winner: null };
  renderGame();
}

function renderGame() {
  const g = state.ttt;
  const box = $("gameBoard");
  box.innerHTML = g.board.map((c, i) => `<button class="cell" data-i="${i}">${c}</button>`).join("");
  box.querySelectorAll(".cell").forEach((b) => { b.onclick = () => playMove(+b.dataset.i); });
  $("gameStatus").textContent = g.winner
    ? (g.winner === "draw" ? "Seri!" : `Pemenang: ${g.winner}`)
    : `Giliran ${g.turn}`;
}

function playMove(i) {
  const g = state.ttt;
  if (g.winner || g.board[i]) return;
  g.board[i] = g.turn;
  const won = LINES.some(([a, b, c]) => g.board[a] && g.board[a] === g.board[b] && g.board[a] === g.board[c]);
  if (won) g.winner = g.turn;
  else if (g.board.every(Boolean)) g.winner = "draw";
  else g.turn = g.turn === "X" ? "O" : "X";
  renderGame();
}

/* ---------- Detail modal ---------- */

function presetCode(p) {
  return JSON.stringify({
    name: p.title,
    app: "Alight Motion",
    category: p.cat,
    version: "5.0",
    layers: [
      { type: "effect", name: p.title, intensity: 0.8, blend: "screen" },
      { type: "transform", scale: [1, 1.08], durationMs: 420 }
    ],
    note: "Demo struktur preset. Tempel sesuai alur proyek AM kamu."
  }, null, 2);
}

function presetFile(p) {
  const blob = new Blob([presetCode(p)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = p.title.toLowerCase().replace(/[^a-z0-9]+/g, "-") + ".json";
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  toast("File preset diunduh");
}

function profileCard(d, username) {
  const name = d.displayName || username || "Tamu";
  let banner;
  if (d.bannerType === "video" && d.bannerUrl) {
    banner = `<video class="banner" src="${d.bannerUrl}" muted loop autoplay playsinline></video>`;
  } else if (d.bannerType === "image" && d.bannerData) {
    banner = `<div class="banner" style="background-image:url('${d.bannerData}')"></div>`;
  } else {
    banner = `<div class="banner" style="background:${gradient(3)}"></div>`;
  }
  const links = (d.links || []).map((l) => /^https?:\/\//i.test(l)
    ? `<a class="link-chip" href="${esc(l)}" target="_blank" rel="noopener">${esc(l)}</a>`
    : `<span class="link-chip">${esc(l)}</span>`).join("");
  return `
    <div class="profile-card">
      ${banner}
      <div class="profile-body">
        <div class="avatar big">${esc(name.slice(0, 1).toUpperCase())}</div>
        <h2>${esc(name)}</h2>
        <p class="muted">@${esc(username || "tamu")}</p>
        <p style="margin-top:8px">${esc(d.bio || "")}</p>
        <div class="links">${links}</div>
      </div>
    </div>`;
}

function openDetail(kind, id) {
  const body = $("modalBody");
  if (kind === "video") {
    const v = videos.find((x) => x.id === id);
    const url = "https://www.youtube.com/results?search_query=" + encodeURIComponent(v.q + " Alight Motion");
    body.innerHTML = `
      <h2>${esc(v.title)}</h2>
      <p>${esc(v.cat)} · ${esc(v.dur)} · ${esc(v.views)} tontonan</p>
      ${v.yt
        ? `<div class="yt-embed"><iframe src="https://www.youtube.com/embed/${v.yt}" allowfullscreen loading="lazy"></iframe></div>`
        : `<div class="thumb" style="height:220px;border-radius:16px"><img class="thumb-cover thumb-yt-img" src="${IMG_YT}" alt="" /></div>`}
      <div class="row" style="margin-top:16px">
        <a class="btn primary" href="${url}" target="_blank" rel="noopener">Cari di YouTube</a>
        <button class="btn ghost" id="copyQuery">Salin kata kunci</button>
      </div>`;
    body.querySelector("#copyQuery").onclick = () => { navigator.clipboard.writeText(v.q); toast("Kata kunci disalin"); };
  } else if (kind === "preset") {
    const p = presets.find((x) => x.id === id);
    body.innerHTML = `
      <h2>${esc(p.title)}</h2>
      <p>${esc(p.desc)}</p>
      <div class="codebox">${esc(presetCode(p))}</div>
      <div class="row">
        <button class="btn primary" id="copyPreset">Salin kode preset</button>
        <button class="btn ghost" id="dlPreset">Unduh file</button>
      </div>`;
    body.querySelector("#copyPreset").onclick = () => { navigator.clipboard.writeText(presetCode(p)); toast("Kode preset disalin"); };
    body.querySelector("#dlPreset").onclick = () => presetFile(p);
  } else if (kind === "template") {
    const t = templates.find((x) => x.id === id);
    body.innerHTML = `
      <h2>${esc(t.title)}</h2>
      <p>${esc(t.desc)} · Rasio ${esc(t.ratio)}</p>
      <div class="thumb" style="height:220px;border-radius:16px;background:${gradient(5)}">${SQUARE_ICON}</div>
      <div class="row" style="margin-top:16px">
        <button class="btn primary" id="useTpl">Pakai template</button>
        <button class="btn ghost" id="copyTpl">Salin outline scene</button>
      </div>`;
    const outline = `${t.title}\nRasio: ${t.ratio}\nKategori: ${t.cat}\nAdegan: Hook → Isi → CTA`;
    body.querySelector("#useTpl").onclick = () => toast("Template ditambahkan ke proyek");
    body.querySelector("#copyTpl").onclick = () => { navigator.clipboard.writeText(outline); toast("Outline disalin"); };
  } else if (kind === "shared") {
    const s = load(KEYS.shared, []).find((x) => x.id === id);
    if (!s) return;
    body.innerHTML = `
      <h2>${esc(s.title)}</h2>
      <p>${esc(s.desc || "Tanpa deskripsi")} · oleh @${esc(s.owner)}</p>
      <div class="row" style="margin-top:16px"><button class="btn primary" id="dlShared">Unduh file</button></div>`;
    body.querySelector("#dlShared").onclick = () => {
      const a = document.createElement("a");
      a.href = s.dataUrl;
      a.download = s.fileName;
      document.body.appendChild(a);
      a.click();
      a.remove();
    };
  } else if (kind === "user") {
    const u = load(KEYS.users, []).find((x) => x.username === id);
    if (!u) return;
    body.innerHTML = profileCard(u, u.username);
  }
  openModal();
}

/* ---------- Asisten ---------- */

const quotaKey = () => myName() + ":" + new Date().toISOString().slice(0, 10);
const remainingQuota = () => DAILY_LIMIT - ((load(KEYS.quota, {}))[quotaKey()] || 0);
function useQuota() {
  const q = load(KEYS.quota, {});
  q[quotaKey()] = (q[quotaKey()] || 0) + 1;
  save(KEYS.quota, q);
}

function renderAssistantHeader() {
  $("modelSelect").innerHTML = MODELS.map((m) => `<option value="${m.id}" ${m.id === state.model ? "selected" : ""}>${esc(m.label)}</option>`).join("");
  $("quotaText").textContent = `Sisa pesan hari ini: ${remainingQuota()} dari ${DAILY_LIMIT}`;
}

function parseVideoLink(text) {
  const yt = text.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([A-Za-z0-9_-]{11})/);
  if (yt) return { type: "youtube", id: yt[1] };
  if (/tiktok\.com/i.test(text)) return { type: "tiktok" };
  return null;
}

function findUrl(text) {
  const m = text.match(/(?:https?:\/\/|www\.)\S+/i);
  return m ? m[0] : null;
}

function searchPresets(q) {
  const words = q.toLowerCase().split(/\s+/).filter((w) => w.length > 1);
  if (!words.length) return [];
  return presets
    .map((p) => {
      const hay = (p.title + " " + p.cat + " " + p.desc).toLowerCase();
      return { p, score: words.reduce((n, w) => n + (hay.includes(w) ? 1 : 0), 0) };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .map((x) => x.p);
}

function asstAdd(role, html) {
  const log = $("asstLog");
  const el = document.createElement("div");
  el.className = "bubble " + role;
  el.innerHTML = html;
  log.appendChild(el);
  log.scrollTop = log.scrollHeight;
  return el;
}

function asstReply(text) {
  const url = findUrl(text);
  if (url) {
    const link = parseVideoLink(url);
    if (link && link.type === "tiktok") {
      asstAdd("bot", "Link TikTok terdeteksi. Tulis nama presetnya untuk dicari di daftar yang tersedia.");
      return;
    }
    if (link && link.type === "youtube") {
      asstAdd("bot", `Video YouTube terdeteksi. Ini bannernya.
        <div class="am-banner" style="background-image:url(https://img.youtube.com/vi/${link.id}/hqdefault.jpg)"></div>
        <b>Peringatan:</b> tautan ini bukan dari TikTok, jadi tidak ada file yang diberikan. Hati-hati dengan file dari sumber yang tidak dikenal.`);
      return;
    }
    asstAdd("bot", "<b>Peringatan:</b> tautan ini bukan dari TikTok, jadi tidak ada file yang diberikan. Hati-hati dengan file dari sumber yang tidak dikenal.");
    return;
  }

  const results = searchPresets(text);
  if (results.length) {
    const rows = results.slice(0, 5).map((p) => `
      <div class="am-row">
        <div><b>${esc(p.title)}</b><small>${esc(p.cat)} · ${esc(p.desc)}</small></div>
        <button class="btn primary small" data-dl="${p.id}">Unduh file</button>
      </div>`).join("");
    const el = asstAdd("bot", `Ketemu ${results.length} preset yang sesuai:${rows}`);
    el.querySelectorAll("[data-dl]").forEach((b) => { b.onclick = () => presetFile(presets.find((x) => x.id === b.dataset.dl)); });
    return;
  }

  const label = (MODELS.find((m) => m.id === state.model) || MODELS[0]).label;
  asstAdd("bot", `Asisten belum terhubung ke server. Setelah backend siap, pesan ini akan diteruskan ke ${esc(label)}.`);
}

function asstSend(raw) {
  const text = raw.trim();
  if (!text || state.busy) return;
  if (remainingQuota() <= 0) {
    asstAdd("bot", "Limit harian kamu sudah habis. Coba lagi besok.");
    return;
  }
  useQuota();
  renderAssistantHeader();
  asstAdd("user", esc(text));
  state.busy = true;
  const loader = asstAdd("bot loading", `<span class="shimmer-text">MOVA</span> <span class="dots">sedang berpikir</span>`);
  setTimeout(() => {
    loader.remove();
    state.busy = false;
    asstReply(text);
  }, 800);
}

/* ---------- Musik ---------- */

function spotifyEmbed(raw) {
  const m = raw.match(/open\.spotify\.com\/(?:intl-[a-z]+\/)?(track|album|playlist|episode|show)\/([A-Za-z0-9]+)/);
  return m ? `https://open.spotify.com/embed/${m[1]}/${m[2]}` : null;
}

function playSpotify() {
  const raw = $("spotifyInput").value.trim();
  const msg = $("spotifyMsg");
  const src = spotifyEmbed(raw);
  if (!src) {
    $("spotifyPlayer").innerHTML = "";
    if (!raw) msg.textContent = "Tempel link Spotify dulu.";
    else if (raw.includes("spotify")) msg.textContent = "Link Spotify tidak valid. Pakai link track, album, atau playlist.";
    else msg.innerHTML = `Pencarian nama lagu butuh akses Spotify. <a class="text-btn" href="https://open.spotify.com/search/${encodeURIComponent(raw)}" target="_blank" rel="noopener">Cari "${esc(raw)}" di Spotify</a>, lalu salin linknya ke sini.`;
    return;
  }
  msg.textContent = "Memutar dari Spotify…";
  $("spotifyPlayer").innerHTML = `<iframe class="spotify-frame" src="${src}" width="100%" height="352" frameborder="0" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>`;
}

/* ---------- Chat ---------- */

function loadMessages() {
  state.messages = load(KEYS.chat, []);
  if (!state.messages.length) {
    state.messages = [
      { id: "s1", system: true, text: "Selamat datang di Chat Global MOVA.", ts: Date.now() - 60000 },
      { id: "s2", system: true, text: "Mode lokal: pesan hanya terlihat di perangkat ini sampai server tersedia.", ts: Date.now() - 40000 }
    ];
  }
}

function renderMessages() {
  const box = $("messages");
  box.innerHTML = state.messages.map((m) => {
    if (m.system) return `<div class="msg system"><div class="body">${esc(m.text)}</div></div>`;
    const mine = m.userId === myId();
    const time = new Date(m.ts).toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" });
    return `<div class="msg ${mine ? "mine" : ""}"><div class="who">${mine ? "Kamu" : esc(m.user)} · ${time}</div><div class="body">${esc(m.text)}</div></div>`;
  }).join("");
  box.scrollTop = box.scrollHeight;
}

function pushMessage(msg, broadcast) {
  state.messages.push(msg);
  save(KEYS.chat, state.messages.slice(-120));
  renderMessages();
  if (broadcast && channel) channel.postMessage({ type: "chat", msg });
}

function sendChat(text) {
  const clean = text.trim();
  if (!clean) return;
  pushMessage({
    id: crypto.randomUUID(),
    userId: myId(),
    user: getProfile().displayName || myName(),
    text: clean,
    ts: Date.now()
  }, true);
}

function renderOnline() {
  const names = [(getProfile().displayName || myName()) + " (kamu)", ...[...state.peers.values()].map((p) => p.name)];
  $("userList").innerHTML = names.map((n) => `<li>${esc(n)}</li>`).join("");
  $("onlineCount").textContent = names.length + " online";
  $("statOnline").textContent = names.length;
}

function setConn(ok, label) {
  $("connDot").className = "dot " + (ok ? "ok" : "");
  $("connLabel").textContent = label;
  $("chatStatus").textContent = ok
    ? "Tersambung realtime antar tab di perangkat ini."
    : "Mode lokal. Pesan hanya terlihat di perangkat ini sampai server tersedia.";
}

function presenceTick() {
  if (channel) {
    channel.postMessage({ type: "hello", user: { id: myId(), name: getProfile().displayName || myName() }, ts: Date.now() });
    setConn(true, "Realtime aktif");
  } else {
    setConn(false, "Mode lokal");
  }
  const now = Date.now();
  for (const [id, peer] of state.peers) {
    if (now - peer.ts > 8000) state.peers.delete(id);
  }
  renderOnline();
}

function tryRemoteServer() {
  // Hook untuk server nanti: isi "mova-ws" di localStorage dengan URL WebSocket.
  const url = localStorage.getItem("mova-ws");
  if (!url) return;
  try {
    const ws = new WebSocket(url);
    ws.addEventListener("open", () => setConn(true, "Server global"));
    ws.addEventListener("message", (ev) => {
      const data = JSON.parse(ev.data);
      if (data.type === "chat" && data.msg && !state.messages.some((m) => m.id === data.msg.id)) {
        pushMessage(data.msg, false);
      }
    });
    ws.addEventListener("close", () => setConn(false, "Server terputus"));
    state.ws = ws;
  } catch {
    setConn(false, "Server tidak tersedia");
  }
}

/* ---------- Pengguna & profil ---------- */

function renderUsers() {
  const q = $("userSearch").value.trim().toLowerCase();
  const list = load(KEYS.users, []).filter((u) => !q || (u.username + " " + (u.displayName || "")).toLowerCase().includes(q));
  $("userList2").innerHTML = list.length
    ? list.map((u) => `
        <article class="user-row" data-open="user" data-id="${esc(u.username)}">
          <div class="avatar small">${esc((u.displayName || u.username).slice(0, 1).toUpperCase())}</div>
          <div><b>${esc(u.displayName || u.username)}</b><small>@${esc(u.username)}</small></div>
        </article>`).join("")
    : `<p class="empty">Belum ada user. Masuk lewat menu Profil untuk mendaftar.</p>`;
  bindOpen($("userList2"));
}

function renderAvatar() {
  const u = currentUser();
  const p = getProfile();
  const name = p.displayName || (u ? u.username : "M");
  $("userAvatar").textContent = name.slice(0, 1).toUpperCase();
  $("sessionBox").innerHTML = u
    ? `<div class="avatar small">${esc(name.slice(0, 1).toUpperCase())}</div><div><b>@${esc(u.username)}</b><small>Masuk</small></div>`
    : `<div class="avatar small">?</div><div><b>Belum masuk</b><small>Klik untuk masuk</small></div>`;
}

function draftProfile() {
  const saved = getProfile();
  const pending = pendingBanner;
  return {
    displayName: $("pName").value.trim(),
    bio: $("pBio").value.trim(),
    links: $("pLinks").value.split(",").map((s) => s.trim()).filter(Boolean),
    bannerType: pending ? pending.type : saved.bannerType,
    bannerData: pending ? (pending.persist ? pending.url : "") : saved.bannerData,
    bannerUrl: pending && pending.type === "video" ? pending.url : ""
  };
}

function previewProfile() {
  const u = currentUser();
  $("profilePreview").innerHTML = profileCard(draftProfile(), u ? u.username : "");
}

function renderProfilePage() {
  const u = currentUser();
  const p = getProfile();
  $("authLoggedOut").hidden = !!u;
  $("authLoggedIn").hidden = !u;
  if (u) $("authName").textContent = "@" + u.username;
  $("pName").value = p.displayName || "";
  $("pBio").value = p.bio || "";
  $("pLinks").value = (p.links || []).join(", ");
  previewProfile();
}

/* ---------- Navigasi & render awal ---------- */

function renderAll() {
  renderAvatar();
  renderHome();
  renderVideos();
  renderPresets();
  renderTemplates();
  renderMusic();
  renderStickers();
  renderAssistantHeader();
  renderMessages();
  renderOnline();
  renderUsers();
  renderProfilePage();
}

function goto(page) {
  state.page = page;
  document.querySelectorAll(".page").forEach((p) => p.classList.toggle("active", p.id === "page-" + page));
  document.querySelectorAll(".nav-btn").forEach((b) => b.classList.toggle("active", b.dataset.page === page));
  $("sidebar").classList.remove("open");
  document.querySelector("main").scrollTop = 0;
  const views = {
    home: renderHome,
    video: renderVideos,
    preset: renderPresets,
    music: renderMusic,
    template: renderTemplates,
    game: renderGame,
    chat: () => { renderMessages(); $("chatInput").focus(); },
    assistant: () => { renderAssistantHeader(); $("asstInput").focus(); },
    users: renderUsers,
    profile: renderProfilePage
  };
  if (views[page]) views[page]();
}

function boot() {
  loadMessages();
  resetGame();
  renderAll();
  showTime();
  setInterval(showTime, 1000);
  presenceTick();
  setInterval(presenceTick, 2500);
  tryRemoteServer();

  if (channel) {
    channel.onmessage = (ev) => {
      const data = ev.data || {};
      if (data.type === "hello" && data.user && data.user.id !== myId()) {
        state.peers.set(data.user.id, { ...data.user, ts: Date.now() });
        renderOnline();
      }
      if (data.type === "chat" && data.msg && data.msg.userId !== myId()) {
        if (!state.messages.some((m) => m.id === data.msg.id)) pushMessage(data.msg, false);
      }
    };
  }

  document.querySelectorAll(".nav-btn").forEach((b) => { b.onclick = () => goto(b.dataset.page); });
  document.querySelectorAll("[data-goto]").forEach((b) => { b.onclick = () => goto(b.dataset.goto); });
  $("sessionBox").onclick = () => goto("profile");
  $("menuBtn").onclick = () => $("sidebar").classList.toggle("open");
  $("overlay").onclick = closeModal;
  $("modalClose").onclick = closeModal;

  $("globalSearch").addEventListener("input", (e) => {
    state.query = e.target.value.trim().toLowerCase();
    if (state.query && state.page === "home") goto("video");
    renderVideos();
    renderPresets();
    renderTemplates();
  });

  $("chatForm").onsubmit = (e) => {
    e.preventDefault();
    sendChat($("chatInput").value);
    $("chatInput").value = "";
  };

  $("modelSelect").onchange = (e) => { state.model = e.target.value; };
  $("asstForm").onsubmit = (e) => {
    e.preventDefault();
    asstSend($("asstInput").value);
    $("asstInput").value = "";
  };

  $("stageClear").onclick = () => { $("stage").innerHTML = ""; };
  $("gameReset").onclick = resetGame;

  $("spotifyPlay").onclick = playSpotify;
  $("spotifyInput").addEventListener("keydown", (e) => { if (e.key === "Enter") playSpotify(); });

  $("shareForm").onsubmit = (e) => {
    e.preventDefault();
    const file = $("sFile").files[0];
    if (!file) return toast("Pilih file dulu");
    if (file.size > SHARE_MAX) return toast("File maksimal 500 KB");
    const reader = new FileReader();
    reader.onload = () => {
      const list = load(KEYS.shared, []);
      list.unshift({
        id: "s" + Date.now(),
        title: $("sTitle").value.trim(),
        desc: $("sDesc").value.trim(),
        owner: myName(),
        fileName: file.name,
        dataUrl: reader.result,
        at: Date.now()
      });
      try { save(KEYS.shared, list); }
      catch { return toast("Penyimpanan penuh. Hapus preset lama dulu."); }
      $("shareForm").reset();
      toast("Preset dibagikan");
      renderPresets();
    };
    reader.readAsDataURL(file);
  };

  $("userSearch").addEventListener("input", renderUsers);

  $("loginForm").onsubmit = (e) => {
    e.preventDefault();
    const username = $("lUser").value.trim().toLowerCase();
    const pass = $("lPass").value;
    if (!/^[a-z0-9_]{3,20}$/.test(username)) return toast("Username 3–20 huruf, angka, atau _");
    if (pass.length < 6) return toast("Password minimal 6 karakter");
    save(KEYS.session, { username });
    upsertUser(username, getProfile());
    $("lPass").value = "";
    toast("Masuk sebagai @" + username);
    renderAll();
  };

  $("logoutBtn").onclick = () => {
    localStorage.removeItem(KEYS.session);
    toast("Kamu sudah keluar");
    renderAll();
  };

  $("googleBtn").onclick = () => toast("Masuk dengan Google aktif setelah server siap");

  ["pName", "pBio", "pLinks"].forEach((id) => $(id).addEventListener("input", previewProfile));

  $("pBannerFile").onchange = (e) => {
    const f = e.target.files[0];
    if (!f) return;
    if (f.type.startsWith("video/")) {
      pendingBanner = { type: "video", url: URL.createObjectURL(f), persist: false };
      previewProfile();
      toast("Banner video hanya tampil di sesi ini");
    } else if (f.type.startsWith("image/")) {
      if (f.size > 1.5 * 1024 * 1024) return toast("Gambar maksimal 1,5 MB");
      const reader = new FileReader();
      reader.onload = () => {
        pendingBanner = { type: "image", url: reader.result, persist: true };
        previewProfile();
      };
      reader.readAsDataURL(f);
    }
  };

  $("profileForm").onsubmit = (e) => {
    e.preventDefault();
    const d = draftProfile();
    const toSave = { displayName: d.displayName, bio: d.bio, links: d.links, bannerType: d.bannerType, bannerData: d.bannerData };
    save(KEYS.profile, toSave);
    const u = currentUser();
    if (u) upsertUser(u.username, toSave);
    if (!(pendingBanner && pendingBanner.type === "video")) pendingBanner = null;
    toast("Profil disimpan");
    renderAll();
  };
}

boot();
